using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve old property name so existing documents are still readable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: id format changed from "Blog|<key>" to just "<key>".
        // Preserve the old "EntityType|Key" format for existing documents.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Breaking change 3: HasIndex() now throws for Cosmos provider — removed.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: Sync I/O now throws by default in Cosmos provider.
        // If you still need sync calls, opt back in. Prefer migrating to async instead.
        base.OnConfiguring(optionsBuilder);
    }
}

// Value generator that reproduces the EF Core 8 "Discriminator|Key" id format
